-- A bounty's overview is versioned, and a sandbox version records the
-- bounty version it was built on.
--
-- Generated by drizzle-kit, then edited by hand at the end: every bounty's
-- text as it stands is its overview's version 1, and a sandbox version whose
-- task was taken from its proposal's current approval records that version.
-- One taken from an approval since moved past cannot be told apart from one
-- before an unchanged re-approval, so it is left null and reads as built on
-- an earlier version.
CREATE TABLE "bounty_version" (
	"bounty_id" text NOT NULL,
	"version" integer NOT NULL,
	"title" text NOT NULL,
	"description" text NOT NULL,
	"created_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "bounty_version_bounty_id_version_pk" PRIMARY KEY("bounty_id","version"),
	CONSTRAINT "bounty_version_version_check" CHECK ("bounty_version"."version" > 0)
);
