UPDATE "sandbox_version_source" s
SET "proposal_version" = p."version"
FROM "bounty_proposal" p
WHERE p."id" = s."approved_task"->'pricing'->>'proposalId'
  AND s."approved_task"->'pricing'->>'status' = 'approved'
  AND p."version" > 0
  AND p."version_revision" = (s."approved_task"->'pricing'->>'proposalRevision')::integer;